package java.util.logging;
public class Level { public static final Level ALL=new Level("ALL",Integer.MIN_VALUE),FINEST=new Level("FINEST",300),FINER=new Level("FINER",400),FINE=new Level("FINE",500),CONFIG=new Level("CONFIG",700),INFO=new Level("INFO",800),WARNING=new Level("WARNING",900),SEVERE=new Level("SEVERE",1000),OFF=new Level("OFF",Integer.MAX_VALUE); private final String name;private final int value; protected Level(String name,int value){this.name=name;this.value=value;} public String getName(){return name;} public int intValue(){return value;} public String toString(){return name;} }
